INSERT INTO profiles (id, user_id, summary, skills, education, projects, interests, experience, industries, preferred_work_type, experience_level, location, updated_at) VALUES
  ('p_t_s01', 'u_t_s01', 'Third-year Computer Science student focused on backend development, APIs and databases. Has shipped a campus app used by hundreds of students and enjoys making systems fast and reliable.', '["Java", "Spring Boot", "MyBatis", "MySQL", "REST APIs", "Git", "Docker", "Python", "Linux", "JUnit"]', '[{"school": "University of Calgary", "degree": "BSc Computer Science (GPA 3.7/4.0)", "end": "2027"}, {"school": "Western Canada High School", "degree": "High School Diploma, IB Program", "end": "2023"}]', '[{"name": "Campus Marketplace", "bullets": ["Built a Spring Boot REST API used by 300+ students to buy and sell textbooks", "Designed the MySQL schema and indexes, cutting search time from 1.2s to 150ms", "Containerised the app with Docker and deployed it on a free cloud tier"]}, {"name": "Study Room Booking Bot", "bullets": ["Wrote a Python Discord bot that books library study rooms for 40+ classmates", "Added reminder notifications that reduced no-shows by about 30%"]}, {"name": "Hackathon: Food Bank Inventory", "bullets": ["Led a team of 4 to build an inventory tracker in 24 hours", "Won 2nd place out of 35 teams at a campus hackathon"]}]', '["backend", "cloud", "developer tools"]', '[{"title": "IT Support Assistant", "org": "University of Calgary IT", "start": "2025-05", "end": "2025-08", "bullets": ["Resolved 200+ help-desk tickets with a 95% satisfaction score", "Wrote a Python script that automated laptop setup, saving about 15 minutes per device"]}, {"title": "Teaching Assistant, Intro to Programming", "org": "University of Calgary", "start": "2025-09", "end": "2025-12", "bullets": ["Ran weekly labs for 30 first-year students on Java fundamentals", "Graded assignments and held office hours twice a week"]}, {"title": "Barista (part-time)", "org": "Bean There Cafe (fictional)", "start": "2023-06", "end": "2024-08", "bullets": ["Served 150+ customers per shift while training 3 new staff"]}]', '["Software", "Energy"]', 'Startup', 'student', 'Calgary, AB', '2026-11-07 12:00:00'),
  ('p_t_s02', 'u_t_s02', 'Statistics student who turns messy public data into clear dashboards and insights. Comfortable with Python, SQL and Tableau, and interested in using data to improve health and public services.', '["Python", "pandas", "NumPy", "SQL", "PostgreSQL", "Tableau", "Power BI", "Excel", "R", "Statistics"]', '[{"school": "University of Alberta", "degree": "BSc Statistics, Minor in Economics", "end": "2026"}]', '[{"name": "Transit Delay Dashboard", "bullets": ["Analysed 1M+ rows of open transit data with pandas", "Published a Tableau dashboard showing delay hot spots, shared by a city councillor''s office"]}, {"name": "ER Wait Time Forecast", "bullets": ["Built an ARIMA model that forecast weekly emergency-room visits within 8% error", "Presented results to a class of 60 and a visiting health analyst"]}, {"name": "Survey Cleaner", "bullets": ["Wrote a reusable Python package to clean and label survey exports, used by 3 student clubs"]}]', '["data", "public policy", "health analytics"]', '[{"title": "Data Analyst Intern", "org": "Municipal transit agency (fictional)", "start": "2025-05", "end": "2025-08", "bullets": ["Automated a monthly Excel report with Python, saving 6 hours per month", "Built 4 Power BI dashboards for the transportation team"]}, {"title": "Research Assistant", "org": "University of Alberta, Dept. of Statistics", "start": "2024-09", "end": "2025-04", "bullets": ["Cleaned and merged 5 census datasets for a professor''s housing study", "Wrote R scripts for regression analysis and charts"]}, {"title": "Math Tutor", "org": "Self-employed", "start": "2022-09", "end": "2024-06", "bullets": ["Tutored 10+ high-school students in calculus and statistics"]}]', '["Health", "Government"]', 'Large company', 'student', 'Edmonton, AB', '2026-11-07 12:00:00'),
  ('p_t_s03', 'u_t_s03', 'Mechanical Engineering student moving into renewable energy and simulation. Combines hands-on design work with Python data analysis of turbine and sensor data.', '["MATLAB", "Python", "SolidWorks", "ANSYS Fluent (CFD)", "AutoCAD", "Excel", "Data analysis", "Technical writing"]', '[{"school": "University of Calgary", "degree": "BSc Mechanical Engineering, Energy and Environment specialisation", "end": "2027"}, {"school": "Politecnico di Milano", "degree": "Exchange semester, Energy Engineering", "end": "2025"}]', '[{"name": "Small Wind Turbine Blade", "bullets": ["Simulated 6 blade designs in ANSYS Fluent", "Improved efficiency by 8% over the baseline design"]}, {"name": "Solar Panel Cleaning Rig", "bullets": ["Designed a low-cost brush rig in SolidWorks for a capstone team of 5", "Raised panel output by 12% in dusty test conditions"]}, {"name": "Home Energy Audit Tool", "bullets": ["Built a MATLAB app that estimates heat loss from room measurements"]}]', '["renewables", "sustainability", "simulation"]', '[{"title": "Engineering Intern", "org": "Prairie Wind Co. (fictional)", "start": "2025-05", "end": "2025-08", "bullets": ["Collected and cleaned 6 months of turbine sensor data in Python", "Found a sensor drift issue that was causing 3% under-reported output"]}, {"title": "Engineering Society Volunteer", "org": "Schulich Engineering Society", "start": "2024-09", "end": "2025-04", "bullets": ["Organised a sustainability design competition with 80 participants"]}, {"title": "Lab Assistant", "org": "University of Calgary Fluids Lab", "start": "2024-01", "end": "2024-04", "bullets": ["Set up wind-tunnel experiments for 4 lab sections"]}]', '["Energy", "Research"]', 'Research lab', 'intermediate', 'Calgary, AB', '2026-11-07 12:00:00'),
  ('p_t_s04', 'u_t_s04', 'First-year software development student exploring front-end development and UX design. Learns fast by building small web projects and enjoys making interfaces easy to use.', '["HTML", "CSS", "JavaScript", "React (learning)", "Figma", "Git", "Canva", "Customer service"]', '[{"school": "SAIT", "degree": "Diploma, Software Development", "end": "2028"}, {"school": "Bishop Carroll High School", "degree": "High School Diploma", "end": "2025"}]', '[{"name": "Personal Portfolio", "bullets": ["Built a responsive portfolio site with vanilla JavaScript and CSS grid", "Reached a 98 Lighthouse accessibility score"]}, {"name": "Recipe Finder", "bullets": ["Made a small React app that searches a free recipe API", "Added filters for diet type and cooking time"]}, {"name": "Club Website Redesign", "bullets": ["Redesigned the school robotics club website in Figma and HTML"]}]', '["design", "web", "accessibility"]', '[{"title": "Retail Associate (part-time)", "org": "ElectroMart (fictional)", "start": "2024-06", "end": "2025-08", "bullets": ["Helped 50+ customers a day choose laptops and phones", "Trained 2 new hires on the point-of-sale system"]}, {"title": "Volunteer Web Helper", "org": "Local community association", "start": "2025-01", "end": "2025-06", "bullets": ["Updated event pages and posters for a neighbourhood group of 400 members"]}]', '["Software"]', 'Startup', 'beginner', 'Calgary, AB', '2026-11-07 12:00:00'),
  ('p_t_s05', 'u_t_s05', 'Biomedical Engineering student applying machine learning to health care. Has trained image classifiers on clinical data and enjoys working between engineers and clinicians.', '["Python", "PyTorch", "scikit-learn", "pandas", "R", "SQL", "Git", "Medical imaging", "Statistics"]', '[{"school": "University of Toronto", "degree": "BASc Biomedical Engineering", "end": "2026"}]', '[{"name": "Skin Lesion Classifier", "bullets": ["Trained a CNN on 10k labelled images", "Reached 87% validation accuracy and added Grad-CAM explanations"]}, {"name": "Wearable Step Counter", "bullets": ["Built a step-detection algorithm for accelerometer data with 95% accuracy", "Wrote a short report comparing 3 filtering methods"]}, {"name": "Hospital Bed Dashboard", "bullets": ["Made a Streamlit dashboard of bed occupancy from synthetic data for a course project"]}]', '["AI", "health", "medical devices"]', '[{"title": "Research Volunteer", "org": "Hospital research lab (fictional)", "start": "2024-09", "end": "2025-04", "bullets": ["Labelled imaging data and ran baseline models", "Co-authored a poster presented at a student research day"]}, {"title": "Machine Learning Intern", "org": "MedVision Startup (fictional)", "start": "2025-05", "end": "2025-08", "bullets": ["Improved an X-ray triage model''s recall from 0.81 to 0.86", "Wrote data-loading pipelines that cut training prep time by half"]}, {"title": "Peer Mentor", "org": "University of Toronto Engineering", "start": "2023-09", "end": "2024-04", "bullets": ["Mentored 8 first-year students through their first term"]}]', '["Health", "Research"]', 'Research lab', 'intermediate', 'Toronto, ON', '2026-11-07 12:00:00'),
  ('p_t_s07', 'u_t_s07', 'Recent Business Technology graduate who connects business needs with technology. Experienced with SQL reporting, process improvement and leading small teams.', '["SQL", "Excel", "Power BI", "Python (basic)", "Jira", "Business analysis", "Project coordination", "Presentation"]', '[{"school": "Mount Royal University", "degree": "Bachelor of Business Administration, Business Technology", "end": "2026"}]', '[{"name": "Inventory Forecast for a Local Bakery", "bullets": ["Built an Excel and Power BI model that reduced food waste by 18%"]}, {"name": "Student Club CRM", "bullets": ["Set up a free CRM and SQL reports for a 200-member club", "Cut the time to send event invites from 2 hours to 15 minutes"]}]', '["business analysis", "product", "operations"]', '[{"title": "Business Analyst Co-op", "org": "Calgary Logistics Co. (fictional)", "start": "2025-01", "end": "2025-08", "bullets": ["Mapped 12 warehouse processes and found 3 bottlenecks", "Wrote SQL queries for weekly KPI reports used by 4 managers"]}, {"title": "Shift Supervisor", "org": "Campus bookstore", "start": "2023-09", "end": "2024-12", "bullets": ["Supervised a team of 6 and handled the daily cash reconciliation"]}]', '["Logistics", "Software"]', 'Large company', 'student', 'Calgary, AB', '2026-11-07 12:00:00'),
  ('p_t_s08', 'u_t_s08', 'Computer Engineering student interested in embedded systems and IoT. Builds hardware projects end to end, from circuit design to firmware and simple cloud dashboards.', '["C", "C++", "Python", "Arduino", "Raspberry Pi", "Embedded C", "PCB design (KiCad)", "MQTT", "Linux"]', '[{"school": "University of Waterloo", "degree": "BASc Computer Engineering", "end": "2027"}]', '[{"name": "Smart Greenhouse Monitor", "bullets": ["Built an ESP32 sensor node that sends temperature and humidity over MQTT", "Made a Grafana dashboard used by a community garden"]}, {"name": "Line-following Robot", "bullets": ["Wrote PID control firmware in C for a robotics competition, placing 4th of 20"]}, {"name": "Custom Macro Keyboard", "bullets": ["Designed a PCB in KiCad and wrote QMK firmware"]}]', '["embedded", "IoT", "robotics"]', '[{"title": "Firmware Co-op", "org": "NorthStar Devices (fictional)", "start": "2025-05", "end": "2025-08", "bullets": ["Fixed 15 firmware bugs in a battery-powered sensor product", "Cut idle power use by 20% with sleep-mode changes"]}, {"title": "Hardware Team Member", "org": "University rocketry design team", "start": "2024-09", "end": "2025-04", "bullets": ["Soldered and tested telemetry boards for a launch"]}]', '["Software", "Energy"]', 'Startup', 'student', 'Waterloo, ON', '2026-11-07 12:00:00');
