-- job_ready test data. Run AFTER db/schema.sql:
--   mysql -uroot -p job_ready_db < db/test-data.sql      (or open it in Navicat and run it)
-- Safe to run again: it first deletes only the test rows it created (ids containing "_t_").
-- Every test account's password is: password123
-- The app loads this file automatically (app.test-data.enabled) when user u_t_s08 or event e_t_10
-- is missing; bump those markers in DataInitializer when you add newer test rows.
-- All companies and postings are fictional.

USE job_ready_db;
SET NAMES utf8mb4;

DELETE FROM coffee_chats   WHERE id LIKE 'c\_t\_%';
DELETE FROM events         WHERE id LIKE 'e\_t\_%';
DELETE FROM mentors        WHERE id LIKE 'm\_t\_%';
DELETE FROM profiles       WHERE id LIKE 'p\_t\_%';
DELETE FROM resumes        WHERE opportunity_id LIKE 'o\_t\_%';
DELETE FROM opportunities  WHERE id LIKE 'o\_t\_%';
DELETE FROM users          WHERE id LIKE 'u\_t\_%';

-- 8 students (u_t_s01..s08; s06 has no profile, to test the questionnaire) and 4 mentors


-- The local admin account (admin@jobready.dev, if it exists) gets a full profile too, so the
-- AI features have something to work with. This replaces its current profile.
DELETE FROM profiles WHERE user_id = 'u_admin';
SELECT 'p_t_admin', id, 'Final-year Software Engineering student who builds full-stack web apps with Java and React. Enjoys backend design, clean APIs and helping teams ship on time.', '["Java", "Spring Boot", "MyBatis", "MySQL", "React", "TypeScript", "REST APIs", "Docker", "Git", "AWS (basic)"]', '[{"school": "University of Calgary", "degree": "BSc Software Engineering", "end": "2026"}]', '[{"name": "Job Ready (hackathon)", "bullets": ["Built the Spring Boot backend for a career platform with AI resume tailoring", "Designed the MySQL schema and 28 REST endpoints"]}, {"name": "Club Event Ticketing", "bullets": ["Built a React + Spring Boot ticketing site that sold 600 tickets for 3 events", "Added QR-code check-in that cut entry lines by half"]}]', '["backend", "full-stack", "AI applications"]', '[{"title": "Software Developer Intern", "org": "Bow Valley Tech (fictional)", "start": "2025-05", "end": "2025-08", "bullets": ["Built 6 REST endpoints in Spring Boot for an internal booking tool", "Wrote JUnit tests that raised coverage from 45% to 75%"]}, {"title": "Teaching Assistant, Data Structures", "org": "University of Calgary", "start": "2024-09", "end": "2025-04", "bullets": ["Led weekly tutorials for 40 students and graded assignments"]}]', '["Software", "Energy"]', 'Startup', 'student', 'Calgary, AB', '2026-11-07 12:00:00'
FROM users WHERE id = 'u_admin';

-- 20 opportunities across job / internship / research and local / remote / abroad


